from datetime import datetime, timezone
from decimal import Decimal
from ledgerly import audit
from ledgerly.adjustments import write_off
from ledgerly.errors import BillingError
from ledgerly.models import Invoice, LineItem

def inv(status="issued"):
    return Invoice("inv_1","cus_1",lines=[LineItem("Seat",1,Decimal("50.00"))],status=status)

# naive rejected
try:
    write_off(inv(), datetime(2026,2,1), "x"); print("FAIL naive")
except BillingError as e: print("naive ok", e.code)

# idempotency replay
i = inv()
r1 = write_off(i, datetime(2026,2,1,tzinfo=timezone.utc), "insolvent", idempotency_key="k1")
r2 = write_off(i, datetime(2026,2,1,tzinfo=timezone.utc), "insolvent", idempotency_key="k1")
print("replay", r1==r2, len(audit.events("invoice_written_off")), audit.events("invoice_written_off")[0]["idempotency_key"])

# invalid state
try:
    write_off(inv("draft"), datetime(2026,2,1,tzinfo=timezone.utc), "x"); print("FAIL state")
except BillingError as e: print("state ok", e.code)

# reason too long
try:
    write_off(inv(), datetime(2026,2,1,tzinfo=timezone.utc), "x"*121); print("FAIL len")
except BillingError as e: print("len ok", e.code)
